"""Contact and Group data models with JSON serialization/deserialization."""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional


@dataclass
class Contact:
    """A single contact entry."""

    id: str = ""
    name: str = ""
    phone: str = ""
    email: str = ""
    tags: List[str] = field(default_factory=list)
    notes: str = ""
    groups: List[str] = field(default_factory=list)
    date_added: str = ""

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> Contact:
        # Ensure list fields default correctly
        for key in ("tags", "groups"):
            if key not in data or data[key] is None:
                data[key] = []
        return cls(**data)

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), indent=2)

    @classmethod
    def from_json(cls, text: str) -> Contact:
        return cls.from_dict(json.loads(text))

    def search_match(self, query: str) -> bool:
        """Case-insensitive search across name/phone/email/notes."""
        q = query.lower()
        for val in (self.name, self.phone, self.email, self.notes):
            if q in val.lower():
                return True
        return False

    def matches_tag(self, tag: str) -> bool:
        """Check if contact has the given tag."""
        return tag.lower() in [t.lower() for t in self.tags]

    def matches_filter(self, name_sub: Optional[str] = None,
                       email_sub: Optional[str] = None,
                       tag: Optional[str] = None) -> bool:
        """Filter by case-insensitive name/email substring and/or tag."""
        if name_sub and name_sub.lower() not in self.name.lower():
            return False
        if email_sub and email_sub.lower() not in self.email.lower():
            return False
        if tag and not self.matches_tag(tag):
            return False
        return True

    def __post_init__(self):
        if not self.date_added:
            self.date_added = datetime.utcnow().isoformat()

"""JSON file persistence layer for the contact book."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Optional

from models import Contact, Group

DEFAULT_FILE = "contacts.json"


class Storage:
    """Reads and writes contacts + groups to a single JSON file."""

    def __init__(self, path: str | os.PathLike[str] = DEFAULT_FILE) -> None:
        self.path = Path(path)

    # -- helpers -------------------------------------------------------------

    def _load(self) -> dict:
        if not self.path.exists():
            return {"contacts": [], "groups": []}
        with open(self.path, encoding="utf-8") as f:
            return json.load(f)

    def _save(self, data: dict) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

    # -- contacts ------------------------------------------------------------

    def add_contact(self, contact: Contact) -> None:
        data = self._load()
        data["contacts"].append(contact.to_dict())
        self._save(data)

    def get_contact(self, contact_id: str) -> Optional[Contact]:
        data = self._load()
        for raw in data["contacts"]:
            if raw["id"] == contact_id:
                return Contact.from_dict(raw)
        return None

    def update_contact(self, contact: Contact) -> bool:
        """Update a contact by id. Returns True if found and updated."""
        data = self._load()
        for i, raw in enumerate(data["contacts"]):
            if raw["id"] == contact.id:
                data["contacts"][i] = contact.to_dict()
                self._save(data)
                return True
        return False

    def delete_contact(self, contact_id: str) -> bool:
        """Delete a contact by id. Returns True if found and deleted."""
        data = self._load()
        before = len(data["contacts"])
        data["contacts"] = [c for c in data["contacts"] if c["id"] != contact_id]
        if len(data["contacts"]) < before:
            # Also remove from any groups
            for g in data.get("groups", []):
                g["members"] = [
                    m for m in g["members"] if m != contact_id
                ]
            self._save(data)
            return True
        return False

    def list_contacts(self) -> list[Contact]:
        data = self._load()
        return [Contact.from_dict(raw) for raw in data["contacts"]]

    # -- groups --------------------------------------------------------------

    def add_group(self, group: Group) -> None:
        data = self._load()
        existing_names = {g["name"] for g in data.get("groups", [])}
        if group.name not in existing_names:
            data.setdefault("groups", []).append(group.to_dict())
            self._save(data)

    def get_group(self, name: str) -> Optional[Group]:
        data = self._load()
        for raw in data.get("groups", []):
            if raw["name"] == name:
                return Group.from_dict(raw)
        return None

    def list_groups(self) -> list[Group]:
        data = self._load()
        return [Group.from_dict(raw) for raw in data.get("groups", [])]

    # -- bulk ----------------------------------------------------------------

    def export_json(self, path: str | os.PathLike[str]) -> None:
        """Write the entire book to a JSON file."""
        data = self._load()
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

    def import_json(self, path: str | os.PathLike[str]) -> None:
        """Overwrite the book from a JSON file."""
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        self._save(data)

    def export_csv(self, path: str | os.PathLike[str]) -> None:
        """Export contacts to CSV (tags/groups joined by semicolons)."""
        import csv

        contacts = self.list_contacts()
        with open(path, "w", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            writer.writerow(
                ["id", "name", "phone", "email", "tags", "notes", "groups", "created_at"]
            )
            for c in contacts:
                writer.writerow(
                    [
                        c.id,
                        c.name,
                        c.phone,
                        c.email,
                        ";".join(c.tags),
                        c.notes,
                        ";".join(c.groups),
                        c.created_at.isoformat() if c.created_at else "",
                    ]
                )

    def import_csv(self, path: str | os.PathLike[str]) -> None:
        """Import contacts from CSV (overwrites existing book)."""
        import csv

        data: dict = {"contacts": [], "groups": []}
        with open(path, newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                tags = [t.strip() for t in row.get("tags", "").split(";") if t.strip()]
                groups = [
                    g.strip()
                    for g in row.get("groups", "").split(";")
                    if g.strip()
                ]
                created_at_str = row.get("created_at", "")
                from datetime import datetime, timezone

                created_at = (
                    datetime.fromisoformat(created_at_str)
                    if created_at_str
                    else None
                )
                contact = Contact(
                    contact_id=row["id"],
                    name=row.get("name", ""),
                    phone=row.get("phone", ""),
                    email=row.get("email", ""),
                    tags=tags,
                    notes=row.get("notes", ""),
                    groups=groups,
                    created_at=created_at,
                )
                data["contacts"].append(contact.to_dict())
        self._save(data)

"""Click command to add a contact with name, phone, email, optional tags and notes."""

import click
from storage import Storage


def register(cli):
    """Register the 'add' subcommand on the given Click group."""

    @cli.command("add")
    @click.option("--name", required=True, help="Contact name.")
    @click.option("--phone", required=True, help="Phone number.")
    @click.option("--email", default="", help="Email address.")
    @click.option("--tags", "-t", multiple=True, help="Tags (repeatable).")
    @click.option("--notes", default="", help="Notes.")
    def add(name: str, phone: str, email: str, tags: tuple, notes: str):
        """Add a new contact."""
        from models import Contact
        storage = Storage()
        contact = Contact(name=name, phone=phone, email=email,
                          tags=list(tags), notes=notes)
        saved = storage.add(contact)
        click.echo(f"Added contact {saved.id}: {saved.name}")

"""Click command to list contacts with filters and sorting."""

import click
from storage import Storage


def register(cli):
    """Register the 'list' subcommand on the given Click group."""

    @cli.command("list")
    @click.option("--tag", default=None, help="Filter by tag.")
    @click.option("--name", default=None, help="Case-insensitive name substring.")
    @click.option("--email", default=None, help="Case-insensitive email substring.")
    @click.option("--sort-by", "-s", type=click.Choice(["name", "date_added"]),
                  default="name", help="Sort by field.")
    def list_contacts(tag: str | None, name: str | None,
                      email: str | None, sort_by: str):
        """List contacts with optional filters and sorting."""
        storage = Storage()
        contacts = storage.load()

        # Apply filters
        filtered = [c for c in contacts if c.matches_filter(
            name_sub=name, email_sub=email, tag=tag)]

        # Sort
        reverse = sort_by == "date_added"
        filtered.sort(key=lambda c: getattr(c, sort_by), reverse=reverse)

        if not filtered:
            click.echo("No contacts found.")
            return

        for c in filtered:
            tags_str = ", ".join(c.tags) if c.tags else ""
            groups_str = ", ".join(c.groups) if c.groups else ""
            line = f"[{c.id}] {c.name} | {c.phone} | {c.email}"
            if tags_str:
                line += f" | tags: {tags_str}"
            if groups_str:
                line += f" | groups: {groups_str}"
            click.echo(line)

"""Click command to edit a contact by id (update any field)."""

import click
from storage import Storage


def register(cli):
    """Register the 'edit' subcommand on the given Click group."""

    @cli.command("edit")
    @click.argument("contact_id", type=str)
    @click.option("--name", default=None, help="New name.")
    @click.option("--phone", default=None, help="New phone.")
    @click.option("--email", default=None, help="New email.")
    @click.option("--tags", "-t", multiple=True, help="Replace tags (repeatable).")
    @click.option("--notes", default=None, help="New notes.")
    def edit(contact_id: str, name: str | None, phone: str | None,
             email: str | None, tags: tuple, notes: str | None):
        """Edit a contact by ID. Only provided fields are updated."""
        storage = Storage()
        existing = storage.get_by_id(contact_id)
        if not existing:
            click.echo(f"Error: Contact with id '{contact_id}' not found.", err=True)
            raise SystemExit(1)

        # Update only provided fields
        if name is not None:
            existing.name = name
        if phone is not None:
            existing.phone = phone
        if email is not None:
            existing.email = email
        if tags:  # Only replace if at least one tag given
            existing.tags = list(tags)
        if notes is not None:
            existing.notes = notes

        updated = storage.update(existing)
        click.echo(f"Updated contact {contact_id}: {updated.name}")

