"""Click command for group support: assign contacts to groups and list members."""

import click
from storage import Storage


def register(cli):
    """Register the 'group' subcommand on the given Click group."""

    @cli.group("group")
    def group():
        """Manage contact groups."""
        pass

    @group.command("add")
    @click.argument("contact_id", type=str)
    @click.option("--name", "-g", required=True, help="Group name to add.")
    def group_add(contact_id: str, name: str):
        """Add a contact to a group."""
        storage = Storage()
        contact = storage.get_by_id(contact_id)
        if not contact:
            click.echo(f"Error: Contact with id '{contact_id}' not found.", err=True)
            raise SystemExit(1)
        if name not in contact.groups:
            contact.groups.append(name)
            storage.update(contact)
        click.echo(f"Added contact {contact_id} to group '{name}'.")

    @group.command("remove")
    @click.argument("contact_id", type=str)
    @click.option("--name", "-g", required=True, help="Group name to remove.")
    def group_remove(contact_id: str, name: str):
        """Remove a contact from a group."""
        storage = Storage()
        contact = storage.get_by_id(contact_id)
        if not contact:
            click.echo(f"Error: Contact with id '{contact_id}' not found.", err=True)
            raise SystemExit(1)
        if name in contact.groups:
            contact.groups.remove(name)
            storage.update(contact)
        click.echo(f"Removed contact {contact_id} from group '{name}'.")

    @group.command("list")
    @click.argument("group_name", type=str)
    def group_list(group_name: str):
        """List all members of a group."""
        storage = Storage()
        contacts = storage.load()
        members = [c for c in contacts if group_name.lower() in
                   [g.lower() for g in c.groups]]
        if not members:
            click.echo(f"No members in group '{group_name}'.")
            return
        for c in members:
            click.echo(f"[{c.id}] {c.name} | {c.phone} | {c.email}")

